#define PI 3.14159265358979
#define CS(a) = vec2(cos(a),sin(a))

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 R = iResolution.xy;
    //vec2 uv = fragCoord/R.xx*2. - vec2(1.,R.y/R.x);
    vec2 uv = (2.*fragCoord-R)/R.x;

    // Time varying pixel color

    //float theta = 0.;//iTime*PI;
    //float theta2 = theta + 2.*PI/3.;
    //float theta3 = theta2 + 2.*PI/3.;
    vec3 angles = vec3(0.,2.*PI/3.,4.*PI/3.);

    float scale = 9.;

    //float x = floor((uv.x*cos(theta)+uv.y*sin(theta))*scale)/scale;
    //float y = floor((uv.x*cos(theta2)+uv.y*sin(theta2))*scale)/scale;
    //float z = floor((uv.x*cos(theta3)+uv.y*sin(theta3))*scale)/scale;
    //int xi = int(floor((uv.x*cos(theta)+uv.y*sin(theta))*scale));
    //int yi = int(floor((uv.x*cos(theta2)+uv.y*sin(theta2))*scale));
    //int zi = int(floor((uv.x*cos(theta3)+uv.y*sin(theta3))*scale));
    vec3 xyz = floor((uv.x*cos(angles)+uv.y*sin(angles))*scale)/scale;
    ivec3 xyzi = ivec3(floor((uv.x*cos(angles)+uv.y*sin(angles))*scale));
    int xi = xyzi.x;
    int yi = xyzi.y;
    int zi = xyzi.z;


    // Output to screen
    //fragColor = vec4(sqrt(x)/2.,sqrt(y)/2.,sqrt(z)/2.,1.0);
    fragColor = vec4( sqrt(xyz)/2., 1);

    if((zi >= -1 && zi <= 2 && 1 == yi) ||
       (zi == 2 && yi <= 0 && yi >= -2) ||
       (zi == -1 && yi <= 0 && yi >= -1) ||
       (zi == 1 && yi == -2)) {
        fragColor=vec4(vec3(.9),1.);
    } 
    else {
        if ((xi >=-1 && xi <= 0 && yi >= -2 && zi >= 0) ||
            (xi >= -5 && xi <= -2 && zi >= 3)
            ) {
            fragColor=vec4(vec3(0.75),1.);
        }
        else {
            if ((xi >= -5 && xi <= -2 &&
                 zi >= -1 && zi <= 1 &&
                 yi >= -1 && yi <= 1)
                 ||
                 (xi >= -1 && xi <= 1) &&
                 (yi <= -2)) {
                fragColor=vec4(vec3(.6),1.);
            }
        }
    }

}
